pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fill: strongest reward
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 6 {
        score -= 60.0 + (6 - post_residual) as f64 * 12.0;
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 260.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain_bonus = if slack <= 8.0 { 22.0 } else { 0.0 };
            let stranded = if slack > 10.0 && slack < 24.0 { 16.0 } else { 0.0 };
            score -= 40.0 - slack.min(40.0) + chain_bonus + stranded;
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += waste * (1.5 + (1.0 - progress) * 1.5);
        }
    }

    // Mild penalty for small-but-not-tiny dead space (best-heuristic idea)
    if post_residual > 6 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.15;
    }

    // Pull residuals toward the mean to keep bins uniform
    score += 0.4 * (pr - mean_residual);

    // Scarcity: strongly prefer using the only/one-of-few fitting bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    } else if fitting_bins_count == 2 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 90.0;
        score -= (1.0 - progress) * 30.0;
        score -= 2.5 * open_bins_count as f64;
        if next_item_size >= 60 {
            score -= 20.0;
        }
        if mean_residual > item_size as f64 * 2.5 && open_bins_count > 3 {
            score += (mean_residual - item_size as f64 * 2.5) * 0.4;
        }
    } else {
        let gap_dev = (pr - mean_residual.max(1.0)).abs();
        if gap_dev < 5.0 {
            score -= 5.0;
        } else if gap_dev > 30.0 {
            score += 3.0;
        }
        if pr > 10.0 && pr < 25.0 {
            score += (25.0 - pr) * 0.6;
        }
    }

    // Quadratic waste term scaled by capacity
    score += 0.3 * pr * pr / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 40.0 + 30.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize post residuals that can't host the next item (dead space).
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * gap / bin_capacity as f64;
    }

    // Compare post residual against mean residual: prefer bins whose remaining space
    // deviates downward (tight packing) relative to the fleet average.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but discourage opening a new
    // bin early in the stream or when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 25.0 * progress - 2.0 * open_bins_count as f64;
        // If the next item is huge, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter fits overall (small post residual is good).
    score += 0.3 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

