pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;

    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && (post_residual as f64) < (item_size as f64 * 0.35) . min (30.0) { 120.0 } else { 0.0 } ;
        let crowd = if open_bins_count == 0 { - 200.0 } else if open_bins_count > 6 { 20.0 } else { 60.0 } ;
        score = 100.0 + crowd - bad_fit ;
        // refined new-bin logic: tightness-aware penalty, borrow from best
        let tightness = item_size as f64 / cap . max (1.0) ;
        score += 30.0 + 40.0 * (1.0 - tightness) ;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 25.0 ; }
        if item_size * 2 >= bin_capacity { score -= 20.0 ; }
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score -= (1.0 - progress) * 25.0 ;
        score -= 2.0 * open_bins_count as f64 ;
        if next_item_size >= 60 { score -= 15.0 ; }
        if mean_residual > item_size as f64 * 2.5 && open_bins_count > 3 {
            score += (mean_residual - item_size as f64 * 2.5) * 0.4 ;
        }
    }

    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 6 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0 ;
    } else if post_residual <= 12 && (post_residual as f64) < mean_residual * 0.6 {
        score -= 20.0 ;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            let progress = step_index as f64 / total_items . max (1) as f64 ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) ;
        }
    }

    score += 0.5 * (pr - mean_residual) ;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 ;
    } else if fitting_bins_count == 2 && bin_residual < bin_capacity {
        score -= 25.0 ;
    }

    if bin_residual != bin_capacity {
        let gap_dev = (pr - mean_residual . max (1.0)) . abs () ;
        if gap_dev < 5.0 { score -= 4.0 ; }
        else if gap_dev > 30.0 { score += 3.0 ; }
        if pr > 10.0 && pr < 25.0 { score += (25.0 - pr) * 0.6 ; }
    }

    score += 0.3 * pr * pr / cap ;
    let score = score * 0.95 + ((open_bins_count as f64 * 1.5) as f64) * 0.05 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Threshold below which a gap is likely dead space (min item is 1,
        // but small gaps rarely match future demand; scale with item size).
        let dead_threshold = (item_size as f64 * 0.35).min(30.0);
        if gap < dead_threshold {
            // Superlinear penalty for creating tiny unusable slivers.
            score += (dead_threshold - gap) * (dead_threshold - gap) * 0.8;
        }
        // Perfect fit: strong reward.
        if post_residual == 0 {
            score -= 150.0;
        } else if post_residual <= 2 {
            score -= 60.0;
        }
    }

    // Open-bins pressure: discourage spreading across too many bins.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (40.0 - slack.min(40.0)) * 0.5;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit here; mildly penalize to prefer bins that
        // leave useful space for the lookahead.
        score += 10.0;
    }

    // Slight preference for tighter bins relative to fleet mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && (post_residual as f64) < (item_size as f64 * 0.35).min(30.0) { 120.0 } else { 0.0 };
        let crowd = if open_bins_count == 0 { -200.0 } else if open_bins_count > 6 { 20.0 } else { 60.0 };
        score = 100.0 + crowd - bad_fit;
    }

    score
}

