pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64); // tiny gap = wasted bin
        } else if post_residual < 20 {
            score += 15.0; // likely dead space for items >= 10
        }
    } else {
        score -= 40.0; // perfect fit: consume the bin completely
    }

    // Reward tight fills generally (small relative waste).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a bin
        if post_residual >= 20 {
            score -= 10.0; // a fresh bin leaves room for future items
        }
        if fitting_bins_count > 0 {
            score += 20.0; // but if open bins can fit, prefer them
        }
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // leftover too small for next item
        }
    }

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

