pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: penalize wasted residual, with a non-linear (quadratic) dead-space term.
    let mut score = post + 40.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: later in the stream, tighten residual aversion.
    score += 30.0 * progress * norm_post;

    // Cubic interaction: very small residuals late in stream are heavily penalized.
    score += 20.0 * progress * norm_post * norm_post * norm_post;

    // Favor bins whose residual is close to the item (tight fit) via smooth reward.
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 15.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * norm_post;

    // New-bin candidate calibration: make empty bins attractive only for poor fits.
    if bin_residual == bin_capacity {
        score = post + 25.0 * norm_post + 60.0 * progress * norm_post - 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction classes. Residuals in [0, 1/8 C] are near-perfect
    // fits and deserve strong reward.
    let eighth = bin_capacity as f64 / 8.0;
    let quarter = bin_capacity as f64 / 4.0;
    let half = bin_capacity as f64 / 2.0;
    let pr = post_residual as f64;

    if pr <= eighth {
        score -= 12.0; // excellent fit class
    } else if pr <= quarter {
        score -= 5.0;  // good fit class
    } else if pr <= half {
        score -= 1.5;  // mediocre fit class
    } else {
        score += 6.0;  // wasteful class: leaves more than half empty
    }

    // Integer-division threshold: exact divisibility of the leftover by
    // plausible small item sizes makes the residual reusable.
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50].iter() {
            if post_residual % d == 0 {
                score -= 3.0;
                break;
            }
        }
    }

    // Lookahead coupling: reward when next item exactly fills the post
    // residual; penalize when next item cannot fit anywhere else and this
    // bin is its only chance.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0; // perfect chaining
        } else if next_item_size < post_residual {
            score -= 2.0;  // next item can still use this bin
        } else {
            score += 2.0;  // next item will need another bin
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // unless the item is large relative to the residual landscape.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 6.0 * (1.0 - progress) - 0.05 * open_bins_count as f64;
        if item_size > 60 {
            score -= 5.0; // big items justify fresh bins
        }
    }

    // Mild tie-breaking: prefer bins whose residual deviates favorably
    // from the mean residual (consolidate small residuals together).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap -> strong penalty
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // marginal gap -> moderate penalty
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness ratio: fraction of the bin's remaining space consumed.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when open bins are nearly full,
        // penalized otherwise.
        score += 30.0 + 12.0 * open_bins_count as f64 * (0.5 + progress);
        if mean_residual > 25.0 {
            score += 20.0; // existing bins still have room; don't open new one
        }
    } else {
        score -= 5.0 * (1.0 - progress); // mild preference for filling existing bins early
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 10.0; // next item would create a dead gap here
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + (5 - post_residual) as f64 * 10.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            // Next item fits here afterwards: good chain potential.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0); // tighter chain = better
        } else {
            // Next item would NOT fit after this placement: penalize dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 2.0;
        }
    }

    // Compare post_residual to mean residual: avoid creating outliers of waste.
    let pr = post_residual as f64;
    if pr > mean_residual + 20.0 {
        score += (pr - mean_residual - 20.0) * 1.5;
    } else if pr < mean_residual - 20.0 {
        score -= (mean_residual - 20.0 - pr).min(30.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bins have poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when necessary.
        score += 80.0;
        // If nothing else fits well (this is the only fitting candidate),
        // reduce the penalty so a fresh bin becomes viable.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // Early in stream, opening bins is cheaper (more future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Mild preference for tighter fits generally.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins with larger residual consumed (denser bins).
    score -= (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin;
    // otherwise penalize creating a residual that blocks the next item.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let gap = (post_residual as u32 - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            let waste = (next_item_size as f64) - (post_residual as f64);
            score += 0.3 * waste;
        }
    }

    // Global state: when many bins are open, prefer consolidation (penalize
    // spreading across bins); when few bins are open, exploration is cheaper.
    let crowding = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.05 * crowding;

    // Prefer bins whose residual deviates favorably from the mean residual
    // (packing into below-average-residual bins consolidates large gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Time horizon: early in the stream, allow more exploration of new bins;
    // late in the stream, be conservative and prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cost of opening a bin grows with progress.
        score += 20.0 + 40.0 * progress;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        // Existing bins get more attractive as the stream progresses.
        score -= 5.0 * progress;
    }

    // Mild preference for larger residual bins when item is large.
    if item_size > 50 {
        score += 0.05 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = x * (1.0 + progress * (1.0 - x)) * (1.0 + 0.5 * progress);

    // Penalize large dead space more strongly as the stream matures.
    score += 2.0 * progress * x * x;

    // Reward tight fits (small post residual) with a smooth non-linear term.
    score -= (1.0 - x) * (1.0 - x) * (1.0 + progress);

    // Last-chance bonus: strongly favor this bin when it is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Lookahead: penalize if the next item cannot fit in the post residual.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        if !fits_next {
            score += 1.0 + 2.0 * progress;
        } else {
            score -= 0.5 * (pr - next_item_size as f64) / cap;
        }
    }

    // Mild preference for keeping fewer open bins as stream progresses.
    score += 0.01 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 / 25
    let r = post_residual % 25;
    let dead = post_residual < 10; // unusable dead space
    if dead { score += 60.0; }

    // Reward exact / near-perfect fits
    if post_residual == 0 { score -= 80.0; }
    else if post_residual <= 5 { score -= 40.0; }

    // Harmonic residue penalty: post_residual in "bad" classes (11..24 mod 25)
    // are hard to fill by future items (sizes 1..100, often >=10).
    if post_residual >= 10 {
        let usable = if post_residual >= 100 { 1.0 } else { (post_residual as f64) / 100.0 };
        let class_fit = match r {
            0 => 1.0,
            1..=9 => 0.9,
            10..=19 => 0.55,
            20..=24 => 0.7,
            _ => 0.6,
        };
        score += (1.0 - class_fit) * usable * 45.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here: penalize small leftovers
            score += 15.0 * (1.0 - (post_residual as f64) / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin would leave big waste
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = 50.0 + waste * 0.8;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 20.0;
        }
        if open_bins_count == 0 { score -= 60.0; }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).sqrt() * (post_residual as f64) * 0.05;

    // Late-stream tightening: waste matters more near the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    // Mean-residual coupling: avoid fragmenting when residuals are already small
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Threshold below which a gap is likely dead space (min item is 1,
        // but small gaps rarely match future demand; scale with item size).
        let dead_threshold = (item_size as f64 * 0.35).min(30.0);
        if gap < dead_threshold {
            // Superlinear penalty for creating tiny unusable slivers.
            score += (dead_threshold - gap) * (dead_threshold - gap) * 0.8;
        }
        // Perfect fit: strong reward.
        if post_residual == 0 {
            score -= 150.0;
        } else if post_residual <= 2 {
            score -= 60.0;
        }
    }

    // Open-bins pressure: discourage spreading across too many bins.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (40.0 - slack.min(40.0)) * 0.5;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit here; mildly penalize to prefer bins that
        // leave useful space for the lookahead.
        score += 10.0;
    }

    // Slight preference for tighter bins relative to fleet mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && (post_residual as f64) < (item_size as f64 * 0.35).min(30.0) { 120.0 } else { 0.0 };
        let crowd = if open_bins_count == 0 { -200.0 } else if open_bins_count > 6 { 20.0 } else { 60.0 };
        score = 100.0 + crowd - bad_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 40.0 + 30.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize post residuals that can't host the next item (dead space).
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * gap / bin_capacity as f64;
    }

    // Compare post residual against mean residual: prefer bins whose remaining space
    // deviates downward (tight packing) relative to the fleet average.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but discourage opening a new
    // bin early in the stream or when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 25.0 * progress - 2.0 * open_bins_count as f64;
        // If the next item is huge, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter fits overall (small post residual is good).
    score += 0.3 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling the bin well (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residuals too small for the smallest items (1..=100 unknown, assume small items ~ up to 20)
    if post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward residual that can hold the next item exactly-ish
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item can't fit here; mild penalty unless residual is tiny waste
            score += 4.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation into existing bins
    let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 0.6 * pressure;
    }

    // Time horizon: early in stream, opening new bins is cheap (score new-bin candidate better);
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline near mean residual trend, penalized late
        score += 15.0 * progress;
        score += 0.3 * mean_residual;
    } else {
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is closest to item size (best-fit flavor)
    score += 0.15 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr_norm * (1.0 + 0.6 * progress) - 0.8 * pr_norm * pr_norm * (1.0 - progress);

    // Smooth interaction: dead space penalty grows quadratically with progress
    score += 0.5 * pr_norm * pr_norm * progress;

    // Last-chance bonus (smooth): strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate: mildly penalize early, mildly reward late
    if bin_residual == bin_capacity {
        score += 0.3 - 0.5 * progress;
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.6 * (1.0 - progress);
    }

    // Encourage balancing against mean residual smoothly
    score += 0.2 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Small leftovers (tight fit) are rewarded.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Class index via integer division thresholds (harmonic classes):
    // 0: [0,10) dead space, 1: [10,25), 2: [25,50), 3: [50,100]
    let class = if post_residual < 10 { 0 }
        else if post_residual < 25 { 1 }
        else if post_residual < 50 { 2 }
        else { 3 };

    // Reward tight fits strongly (dead space is the enemy)
    score -= match class {
        0 => 60.0,
        1 => 30.0,
        2 => 10.0,
        _ => 0.0,
    };

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = post_residual - next_item_size;
        if next_fit == 0 {
            score -= 80.0;
        } else if next_fit < 10 {
            score -= 45.0;
        } else if next_fit < 25 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this leftover: penalize large leftovers
        score += frac * 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables
    // a much better structure. Empty bin has post_residual == capacity.
    if bin_residual == bin_capacity {
        // A fresh bin is only attractive when current bins are congested
        // or the item is huge relative to mean residual.
        let congestion = mean_residual / bin_capacity as f64;
        score += 40.0 - 30.0 * congestion;
        // Large items may warrant a fresh bin late in the stream
        if item_size > 60 && step_index as f64 / total_items as f64 > 0.5 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Modulo harmonic bonus: leftovers that are multiples of common small
    // item sizes (10, 20, 25) are more reusable.
    if post_residual % 10 == 0 { score -= 8.0; }
    else if post_residual % 25 == 0 { score -= 6.0; }

    // Penalize leftover just below common item sizes (unusable gaps)
    for gap in [11u32, 26u32, 51u32] {
        if post_residual >= gap - 2 && post_residual < gap {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can fill are very costly.
    // A residual gap is "unusable" if it is below the minimum item size (1) — instead
    // treat tiny gaps (< 10) as hard dead space, and gaps that the lookahead item
    // cannot use as soft dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            // tiny unusable sliver: heavy penalty
            score += 40.0 + (10 - post_residual) as f64 * 6.0;
        }
        // lookahead-aware dead space: gap that next item cannot fit into
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // perfect closure of the bin: strong reward
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin space consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize spreading across many bins; encourage filling
    // existing bins when many are open.
    score += 0.6 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Mean-residual coupling: if the fleet of open bins is already loose (large mean
    // residual), prefer placements that tighten this bin relative to the fleet.
    score += 0.25 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin should only win when the item is huge
    // (poor fit anywhere) or no open bin fits. Penalize the fresh bin mildly so it
    // is chosen only for large items / desperate cases.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // large items justify a new bin more than small ones
        score += 25.0 - 30.0 * item_frac;
    }

    // Late-stream urgency: as the stream nears its end, avoid leaving open bins
    // with residual space that will never be filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the post-residual -> strong reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect lookahead fit
        } else {
            // Reward proximity of post_residual to next_item_size (soft matching)
            score -= 40.0 / (1.0 + gap * 0.15);
        }
        // Penalize residual too small for the next item (dead space risk),
        // scaled by how far below the next item it falls.
        if (post_residual as f64) < next_item_size as f64 {
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        }
        // Bonus if next item could fit into the post-residual chain (two-in-a-row packing)
        if next_item_size as f64 <= post_residual as f64 {
            score -= 10.0;
        }
    } else {
        // Last item: prefer minimal waste directly.
        score += 5.0;
    }

    // Compare against mean residual: placing into a bin whose residual is near the
    // mean keeps the bin population balanced; extreme residuals are penalized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last-chance bin: if this is the only bin that fits, strongly encourage using it
    // (avoid opening a new bin) when the fit is not terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (dead space below min item size ~1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    // Perfect closure (zero residual) is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Late in the stream, consolidate more aggressively (fewer open bins preferred).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.2;

    // Mild penalty for using an almost-full bin when other bins exist, unless last chance.
    if bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += (bin_capacity - bin_residual) as f64 * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize unusable dead space: post_residual below smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Time horizon: early stream -> prefer consolidating into open bins;
    // late stream -> be pickier, avoid fragmenting residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress); // mild early bonus for reusing bins
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins with slack: encourage filling them rather than opening new ones.
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: penalize bins far from the mean (outliers waste space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New empty bin candidate: penalize mildly unless current fit is poor or
    // item is large relative to residuals.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit || (fitting_bins_count <= 1 && next_item_size > post_residual && next_item_size > 0) {
            score -= 18.0; // opening a new bin is justified
        } else {
            score += 20.0; // prefer existing bins otherwise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: early on, tolerate slack (favor consolidation
    // into existing bins less aggressively); late, penalize residual waste more.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward bins whose post-residual could host the next item (smooth interaction).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let fit_next = (post - next) / cap;
        if fit_next >= 0.0 {
            score -= 12.0 * (1.0 - fit_next) * (1.0 - 0.5 * progress);
        } else {
            // Post-residual becomes dead space relative to next item; penalize smoothly.
            score += 6.0 * (-fit_next) * (1.0 + progress);
        }
    }

    // Last-chance bonus: only one bin fits, encourage using it rather than new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Slight preference for filling bins with below-average residual (balance avoidance
    // of many half-empty bins), smooth in mean_residual.
    score += 0.3 * (mean_residual - post) * (1.0 - progress);

    // New-bin candidate: empty bin gets a smooth handicap that shrinks as stream ends,
    // so a genuinely poor fit late in the stream can still justify a new bin.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 and integer division
    let pr = post_residual;
    let harmonic_class = pr / 10;          // integer division threshold classes
    let residue = pr % 10;                 // modulo residue within class

    // Reward small post_residual, but especially residuals in "usable" classes
    // (residuals >= 10 can still host the smallest item size class).
    if pr == 0 {
        score -= 40.0;                     // perfect fit is ideal
    } else if pr < 10 {
        score += 25.0;                     // dead space below min item size
    } else {
        // Prefer residuals that are multiples of 10 (harmonic alignment with
        // common item size classes); penalize odd residues.
        score -= (harmonic_class as f64) * 2.0;
        score += (residue as f64) * 1.5;
        if residue == 0 {
            score -= 8.0;
        }
    }

    // Capacity-fraction coupling: reward bins whose fill level crosses
    // harmonic fractions of capacity (1/4, 1/2, 3/4).
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    for frac in [0.25f64, 0.5, 0.75] {
        let d = (fill - frac).abs();
        if d < 0.05 {
            score -= 6.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == pr {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0;
    } else if next_item_size > 0 && pr > 0 && next_item_size > pr {
        score += 10.0;                     // next item cannot use this bin
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on
    // a poor fit unless the fit is tight.
    if fitting_bins_count == 1 && pr > 0 {
        if pr < 20 {
            score -= 15.0;                 // tight fit, good use of last chance
        } else {
            score += 12.0;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate default so it is
    // chosen only when no open bin offers a good (small) post_residual.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening new bins is relatively cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Slight preference for consolidating among many open bins.
    score += (open_bins_count as f64) * 0.3;
    score += (mean_residual - pr as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as i32) as f64 * 8.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward using the bin whose residual best matches the item (tight fit signal).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Last-chance bin: avoid opening a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if this bin's residual is far above mean, penalize slightly.
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Lookahead: if next item fits the post residual exactly, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= 12 {
            score += (13 - gap as i32) as f64 * 4.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && (bin_residual as f64 - item_size as f64) > 0.0;
        if decent_fit_exists && fitting_bins_count > 1 {
            score += 30.0; // discourage opening new bin when alternatives exist
        }
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item fills this bin exactly afterwards
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot reuse this residual: penalize proportional to wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 0.6 * miss;
        }
    } else {
        // Last item: prioritize tightest fit strongly
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize creating tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make it unattractive unless residual would be perfect for next item
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 30.0;
        }
    }

    // Early in stream: slightly prefer opening fresh bins to build diverse residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving "awkward" residuals that few item sizes can fill.
    // Residuals in (0, 10) are pure dead space; residuals in (50, 90) are semi-useful.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    } else if post_residual > 50 {
        score -= 4.0 * ((post_residual as f64 - 50.0) / 50.0);
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Bonus if next item exactly fills the remaining space.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if next_item_size > post_residual {
            // Next item won't fit here; penalize wasting residual space it could have used elsewhere.
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a new bin is expensive early, cheap late.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; grows with number of open bins.
        score += 30.0 + 2.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, prefer consolidating: make new bins less attractive
        // unless the fit elsewhere is bad (handled by other terms).
        score += 10.0 * (1.0 - progress);
    } else {
        // Prefer bins with below-mean residual (consolidation strategy).
        score += 2.0 * (bin_residual as f64 - mean_residual).max(0.0) / bin_capacity as f64
            - 1.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;
    }

    // Mild preference for fuller bins overall.
    score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Slight time-variant exploration: early stream favors tight packing,
    // late stream favors minimizing bin count (keep residuals usable).
    if progress < 0.5 {
        score -= 5.0 * fit_ratio;
    } else {
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over progress
    let mut score = pr;

    // Smooth polynomial coupling: dead space penalized more as stream progresses
    let dead = norm_pr * norm_pr;
    score += 40.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tight = 1.0 - norm_pr;
    score -= 12.0 * tight * tight * tight * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in post_residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            // penalize leaving space the next item cannot use
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // plenty of alternatives, mild penalty to prefer better fits
        score += 2.0 * (fitting_bins_count as f64 - 2.0).ln().max(0.0);
    }

    // Prefer bins below mean residual (keep large residuals for large future items)
    let mr = mean_residual / cap;
    let bias = norm_pr - mr;
    score += 6.0 * bias * bias;

    // Mild preference to consolidate into fewer bins early (open new bins cheaply early on)
    score += 3.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize slightly unless post residual would be very small relative to capacity
    if bin_residual == bin_capacity {
        score += 5.0 - 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/4, 1/3, 1/2 of capacity).
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;

    // Dead-space penalty: leftovers too small for typical items are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward residuals that land in "useful" harmonic classes.
    if post_residual >= quarter && post_residual < half {
        score -= 6.0; // quarter-to-half leftover is reusable
    } else if post_residual >= half {
        score -= 10.0; // half or more left is very reusable
    }

    // Exact modulo alignment: residual divisible by common item sizes
    // (10/20/25/50 classes) is likely to be perfectly filled later.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly,
    // strongly reward; if it cannot fit, penalize lightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bins get a mild penalty so we only
    // open them when no open bin offers a decent fit (post_residual of an
    // empty bin is capacity itself, already rewarded by the half+ bonus,
    // so counteract that to keep new bins as fallback).
    if bin_residual == bin_capacity {
        score += 15.0;
        // But early in the stream, or when open bins are crowded, new bins
        // are cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 || mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Prefer bins below mean residual (tighter bins keep slack spread out).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Mild pressure against accumulating many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + (5 - post_residual) as f64 * 10.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0;
        } else if post_residual > next_item_size {
            // Next item fits here afterwards: good chain potential.
            let slack = (post_residual - next_item_size) as f64;
            // Extra reward when the chain leaves another small gap.
            let chain_bonus = if slack <= 5.0 { 15.0 } else { 0.0 };
            score -= 40.0 - slack.min(40.0) + chain_bonus;
        } else {
            // Next item would NOT fit after this placement: penalize dead space,
            // scaled by how much of the stream remains (waste matters more early).
            let waste = (next_item_size - post_residual) as f64;
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += waste * (1.5 + (1.0 - progress) * 1.5);
        }
    }

    // Compare post_residual to mean residual: avoid creating outliers of waste.
    let pr = post_residual as f64;
    if pr > mean_residual + 20.0 {
        score += (pr - mean_residual - 20.0) * 1.5;
    } else if pr < mean_residual - 20.0 {
