    score += open_bins_count as f64 * 0.5 ;
    score += (bin_residual as f64 - mean_residual).abs () * 0.04 ;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let tightness_ratio = item_size as f64 / cap.max (1.0) ;
        score += 30.0 + 35.0 * (1.0 - tightness_ratio) ;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 22.0 ;
        }
        if item_size * 2 >= bin_capacity {
            score -= 18.0 ;
        }
        if post_residual as f64 > mean_residual {
            score += 5.0 ;
        }
        let progress = step_index as f64 / total_items.max (1) as f64 ;
        score += progress * 8.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
