pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    score += 0.3 * pr * pr / cap ;

    // perfect fill: strongly reward
    if post_residual == 0 {
        score -= 900.0 ;
    } else if post_residual <= 6 {
        // near-perfect fill: reward small leftovers
        score -= 40.0 + (6 - post_residual) as f64 * 10.0 ;
    } else if post_residual <= 12 && (post_residual as f64) < mean_residual * 0.6 {
        score -= 20.0 ;
    }

    // lookahead: exact fit for next item is gold
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            let progress = step_index as f64 / total_items . max (1) as f64 ;
            score += waste * (1.2 + (1.0 - progress) * 1.2) ;
        }
    }

    // tightness: prefer bins where item fills most of residual
    let tightness = (bin_residual as f64 - item_size as f64) . abs () ;
    score += tightness * 0.05 ;

    // only fitting bin: keep using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 ;
    }

    score += open_bins_count as f64 * 0.5 ;
    score += (bin_residual as f64 - mean_residual) . abs () * 0.05 ;

    // brand-new empty bin: penalize unless existing fits are poor
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / bin_capacity . max (1) as f64 ;
        score += 30.0 + 40.0 * (1.0 - tight) ;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0 ;
        }
        if item_size * 2 >= bin_capacity {
            score -= 20.0 ;
        }
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score += progress * 8.0 ;
        if post_residual as f64 > mean_residual {
            score -= 5.0 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
