pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable -> heavy penalty.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 20 {
            score += 25.0 * (21.0 - post_residual as f64) / 10.0;
        } else if post_residual >= 90 {
            // near-empty bin after placement: fine, reward
            score -= 10.0;
        }
    } else {
        // perfect fit
        score -= 80.0;
    }

    // Reward filling a bin tightly relative to capacity.
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fill * fill;

    // Open-bin pressure: penalize using bins when many are open (encourage consolidation),
    // but reward closing bins out.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // extra reward if next item nearly exactly consumes the gap
        let gap_diff = (post_residual as i64 - next_item_size as i64) as f64;
        if gap_diff <= 10.0 {
            score -= 12.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < next_item_size {
        // gap too small for next item: penalize more if gap is tiny
        if post_residual < 15 {
            score += 20.0;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else {
            // discourage opening new bin unless all fits are terrible
            score += 70.0
                * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
        }
    }

    // Stream progression: early on, be more conservative about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins where the lookahead item fits exactly into the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect 2-item fill bonus
            score -= 40.0;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space that next item cannot use
            score += 0.6 * (post_residual as f64);
        }
    } else {
        // Last item: just minimize waste
        score -= 15.0;
    }

    // Reward tight fits of the current item
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize bins far above mean residual (wasteful bins) mildly
    score += 0.15 * ((post_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when current item nearly fills a fresh bin
    if bin_residual == bin_capacity {
        if item_size >= 70 || (next_item_size > 0 && item_size + next_item_size >= 95 && item_size + next_item_size <= 100) {
            score -= 45.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (waste ratio)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64) * 0.8;

    // Penalize large dead space quadratically
    score += (post_residual as f64).powi(2) / (bin_capacity as f64) * 0.3;

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * (next_item_size as f64);
        } else {
            // penalize leaving residual that is too small for the next item
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // New-bin candidate: only attractive when no good fits exist
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let best_possible = post_residual; // = 0 for empty bin with item
        score += 30.0; // base reluctance to open new bins
        score -= scarcity * 45.0;
        if fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 20.0; // open bins have plenty of room; discourage new bin
        }
        let _ = best_possible;
    }

    // Time horizon: early in stream, be more willing to open bins (long future)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0;

    // Mild penalty for bins deviating from mean residual (keep balance)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Prefer filling fuller bins slightly
    score -= (bin_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;
    // reward compact packing (quadratic residual penalty) — reinforced direction
    score += 0.45 * pr * pr / cap ;
    let tightness = 1.0 - pr / cap ;
    score -= 18.0 * tightness * tightness ;
    // perfect fill strongly rewarded
    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 6 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0 ;
    } else if post_residual < 10 {
        score -= 12.0 ;
    } else if post_residual < 20 && pr < mean_residual * 0.6 {
        score += 10.0 ;
    }
    // scarcity handling
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 ;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0) ;
    }
    // lookahead coupling with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack.min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            let progress = step_index as f64 / total_items.max (1) as f64 ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) ;
        }
    }
    // global pressure term
    let pressure = open_bins_count as f64 * mean_residual / cap ;
    if bin_residual < bin_capacity {
        score -= 0.6 * pressure ;
    }
    // new-bin candidate logic: open fresh bins when item is large or early stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / cap.max (1.0) ;
        score += 15.0 * progress + 0.3 * mean_residual + 20.0 * (1.0 - tight) ;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0 ;
        }
        if item_size * 2 >= bin_capacity {
            score -= 20.0 ;
        }
    } else {
        score -= 10.0 * progress ;
    }
    score += 0.15 * ((bin_residual - item_size) as f64).abs () ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr / cap;
    // non-linear coupling: post_residual polynomial times progress shaping
    let norm_pr = pr / cap;
    score += 2.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 3.0 * norm_pr * (1.0 - progress) * (norm_pr * (1.0 - norm_pr));
    // prefer filling bins tightly when few fitting bins remain
    if fitting_bins_count == 1 {
        score -= 0.5 * (1.0 - norm_pr);
    }
    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (norm_pr - nxt).abs();
        score -= 0.8 * (1.0 - gap) * (1.0 - progress);
    }
    // penalize diverging from mean residual smoothly
    score += 0.3 * (norm_pr * cap - mean_residual).abs() / cap;
    // new-bin candidate handling: mildly penalize unless residuals are tight
    if bin_residual == bin_capacity {
        score += 0.6 - 0.4 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, small-but-reusable) are rewarded.
    let post = post_residual;
    let class = post % 10;
    if post == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if class == 0 {
        score -= 18.0; // round residual stays reusable for decile-sized items
    } else if post <= 10 {
        score += 25.0; // tiny sliver: near-dead space
    } else if class <= 2 {
        score -= 6.0; // near-round residual is still decent
    } else if class >= 8 {
        score += 8.0; // just above a round number: wasteful
    }

    // Integer-division thresholds: residual that can host a mid-size item.
    if post >= 50 {
        score -= 10.0;
    } else if post >= 30 {
        score -= 4.0;
    } else if post >= 20 {
        score -= 2.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or on a harmonic boundary; penalize otherwise.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 35.0;
        } else if next_item_size <= post {
            let gap = post - next_item_size;
            if gap % 10 == 0 {
                score -= 12.0;
            }
            if gap > 30 {
                score += 6.0; // next item leaves a big awkward hole
            }
        } else {
            // next item won't fit here; residual must survive further future
            score += 10.0;
            if post < 15 {
                score += 10.0; // likely dead space
            }
        }
    } else {
        // Last item: prefer tightest fit, close-out bonus for emptying bins.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64; // new bin's post-residual
        if item_size >= 70 {
            score -= 5.0; // huge items fit anywhere later, fine to open
        }
        if item_size <= 25 && post > 0 {
            score += 12.0; // don't waste a fresh bin on tiny items
        }
        if fitting_bins_count > 0 && item_size <= 50 {
            score += 15.0; // an open bin exists; prefer it for medium items
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // Progress-aware dead-space penalty: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post as f64) * progress * 0.15;

    // Nudge toward bins below mean residual (denser bins) to consolidate waste.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    // A gap is "dead" if it cannot hold even the smallest plausible item.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit: zero waste, reward strongly.
        score -= 50.0;
    } else if post_residual < 10 {
        // Tiny unusable sliver: heavy penalty.
        score += 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap too small for the known next item: moderate dead-space penalty.
        score += 15.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Gap exactly fits the lookahead item: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to bin size (low waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 20.0;

    // Open-bin pressure: prefer existing bins over opening new ones,
    // especially when many bins are already open.
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: penalize proportionally to open bins.
        score += 10.0 + (open_bins_count as f64) * 2.0;
    } else {
        // Existing bin: small discount that grows with bin count pressure.
        score -= 2.0 + (open_bins_count as f64).sqrt() * 1.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Avoid leaving residuals far below the mean residual (fragmentation signal).
    if post_residual as f64 > mean_residual * 1.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect-fill rewards: strongly prefer exact and near-exact matches.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 6 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0;
    } else if post_residual <= 12 && pr < mean_residual * 0.6 {
        score -= 20.0;
    }

    // Next-item lookahead with graded bonuses.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 };
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 };
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 };
            score -= 40.0 - slack.min(40.0) + chain_bonus + stranded + scarcity;
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += waste * (1.5 + (1.0 - progress) * 1.5);
        }
    }

    // Tight-packing pressure relative to fleet mean residual.
    score += 0.5 * (pr - mean_residual);

    // Last-chance bonus: sole fitting bin beats opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count == 2 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 30.0 + 40.0 * (1.0 - tightness);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
        score -= 2.0 * open_bins_count as f64;
        if next_item_size >= 60 {
            score -= 15.0;
        }
        // Penalize opening a new bin when existing residuals already cover needs.
        if mean_residual > item_size as f64 * 2.5 && open_bins_count > 3 {
            score += (mean_residual - item_size as f64 * 2.5) * 0.4;
        }
    } else {
        // Prefer post residuals near the running mean (reusable gap sizes).
        let gap_dev = (pr - mean_residual.max(1.0)).abs();
        if gap_dev < 5.0 {
            score -= 4.0;
        } else if gap_dev > 30.0 {
            score += 3.0;
        }
        // Penalize awkward mid-range residuals that tend to strand space.
        if pr > 10.0 && pr < 25.0 {
            score += (25.0 - pr) * 0.6;
        }
    }

    // Mild quadratic tightness preference.
    score += 0.3 * pr * pr / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: minimize wasted space, but weight against mean residual context.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

