    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin when the item fits poorly
    // in existing bins (large post_residual waste) or when next item is large.
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 {
            post_residual as f64 - next_item_size as f64
        } else {
            post_residual as f64
        };
        if waste_penalty > 0.0 {
            score -= waste_penalty * 0.6;
        }
        // Few open bins => consolidation is fine, discourage new bins early
        score += open_bins_count as f64 * 2.0;
        // Late in stream, new bins are cheap to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Penalize creating very small unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when the bin becomes nearly full.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect lookahead pairing: big reward.
            score -= 30.0;
        } else {
            // Leftover still usable by next item: mild reward.
            score -= 5.0;
        }
    }

    // Early in the stream, allow opening new bins more freely (better long-term
    // packing); late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // If mean residual across open bins is high, discourage spreading into a
    // bin that leaves a large hole; encourage consolidating.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well, i.e.
    // penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        score += 15.0 * (fitting_bins_count as f64);
        // Late in the stream, opening new bins is expensive in expectation.
        score += 25.0 * progress;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Mild penalty for creating very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes large leftover space smoothly

    // Non-linear coupling of post residual with stream progress:
    // late in the stream, waste matters more (fewer chances to fill gaps)
    let progress_coupling = x * (1.0 - x) * (progress - 0.5) * 4.0;
    score += progress_coupling * 10.0;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - x).powf(2.0) * (1.0 + progress) * 8.0;

    // Penalize dead space: residual too small for typical items (smooth logistic-like term)
    let unusable = 1.0 / (1.0 + (x / 0.15).powf(3.0));
    score += unusable * 25.0 * (0.5 + progress);

    // Last-chance bin: strongly favor using it when few bins fit
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0).min(5.0) * 1.5;
    }

    // Lookahead: if next item fits the post residual, reward this placement smoothly
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 - next_item_size as f64) / cap;
        if fits_next >= 0.0 {
            score -= (1.0 - fits_next) * 10.0;
        } else {
            score += (-fits_next / 0.3).min(1.0) * 6.0;
        }
    }

    // Mild penalty for spreading across many open bins; encourage consolidation
    score += (open_bins_count as f64 / 20.0) * (x - mean_residual / cap).abs() * 3.0;

    // Slight preference for fuller bins relative to mean residual
    score -= (mean_residual - post) / cap * 2.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;

    // quadratic dead-space penalty, slightly stronger late in the stream
    score += (0.3 + 0.15 * progress) * pr * pr / cap ;

    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 6 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0 ;
    } else if post_residual <= 12 && pr < mean_residual * 0.6 {
        score -= 20.0 ;
    } else if pr > mean_residual * 1.4 && fitting_bins_count <= 1 {
        // keeping a fat residual in a scarce-fit bin is risky
        score += 6.0 ;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) ;
        }
    }

    // brand-new empty bin candidate
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity . max (1) as f64 ;
        score += 30.0 + 40.0 * (1.0 - tightness) ;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0 ;
        }
        if item_size * 2 >= bin_capacity {
            score -= 20.0 ;
        }
        // late-stream items are cheap to place in existing bins; discourage new bins
        score += 15.0 * progress ;
        // if many bins are already open and fragmented, a fresh bin is more attractive
        if open_bins_count as f64 > 8.0 + 4.0 * mean_residual {
            score -= 10.0 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as u32; // 0..3 harmonic class

    // Reward tight fits (small post_residual), with class-based modulation.
    let tight_bonus = 40.0 * (1.0 - frac).powi(3);
    score -= tight_bonus;

    // Perfect fit: exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space penalty: residuals that are unusable for typical items (1..100).
    // Residuals below 10 (or below 1) are nearly dead; small odd residuals are bad.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual % 2 == 1 && post_residual < 20 {
        score += 8.0;
    }

    // Modulo arithmetic on residual classes: residues near multiples of common
    // item sizes (10, 25, 50) are more reusable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if reusable {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 - 0.2 * slack as f64;
            if slack < 10 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's remainder anyway; penalize
            // leaving a residual that no future small item can absorb.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many options: be pickier about tightness.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Opening a new bin is good when current bin's post-fit residual would be
    // small/dead AND the new bin can serve the lookahead item well.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: keep it competitive but not free.
        score = 35.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins: discourage opening more.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild penalty when this bin's residual deviates far from mean residual
    // (prefer balanced bin usage, keeps harmonic classes predictable).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space penalty: residuals too small for the smallest possible item (1..100 range,
    // but treat gaps < 10 as highly unusable since typical items are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Waste ratio: penalize proportion of capacity left idle relative to the item placed.
    let waste_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += waste_ratio * 25.0;

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    }
    // If next item cannot fit in post-residual but this bin could have held more, mild penalty
    // for fragmenting (next item will need another bin anyway).
    if next_item_size > 0 && next_item_size > post_residual {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (applied relatively: an empty new-bin candidate has bin_residual == bin_capacity,
    // so give it a penalty proportional to open bins to force consolidation).
    if bin_residual == bin_capacity {
        score += 40.0 + 12.0 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins when many are open.
        score -= (open_bins_count as f64).min(20.0);
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter bins first, keeping large gaps in other bins for future large items).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    // Late-stream tightening: as the stream progresses, be stricter about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: this bin absorbs item + next item perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Penalize dead space: post_residual that cannot hold the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space grows worse the smaller it is relative to next item.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste;
        // Tiny unusable slivers are especially bad.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Reward when both current and next item fit (chain continuation).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Tight fit reward relative to residual before placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Compare against mean residual: bins with less residual than average are
    // better targets (consolidate fullness), bins above average are penalized.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Prefer filling existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more later in the stream.
        score += 20.0 + 25.0 * progress;
    }

    // Mild penalty for proliferating open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    // mild quadratic compaction pressure
    score += 0.3 * pr * pr / cap ;

    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 6 {
        score -= 55.0 + (6 - post_residual) as f64 * 10.0 ;
    } else if post_residual <= 12 && pr < mean_residual * 0.6 {
        score -= 20.0 ;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 230.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 20.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 14.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            let progress = step_index as f64 / total_items . max (1) as f64 ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) ;
        }
    }

    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.15 ;
    }

    // new-bin candidate handling: prefer open bins unless the item is large
    // or the fit into open bins would leave dead space
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap . max (1.0) ;
        let mut new_bonus = 30.0 + 40.0 * (1.0 - tightness) ;
        if item_size * 2 >= bin_capacity {
            new_bonus -= 20.0 ;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bonus -= 25.0 ;
        }
        // late in the stream, avoid opening bins for small items
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        if tightness < 0.35 && progress > 0.5 {
            new_bonus += 10.0 ;
        }
        score += new_bonus ;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        score -= (40.0 - slack . min (40.0)) * 0.5 ;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 10.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * dead * dead;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits perfectly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * next_fit;
        } else {
            // Next item won't fit here; slight penalty for leaving tiny unusable gap.
            score += 5.0;
        }
    }

    // Global state: if many bins are open with slack, prefer consolidating into low-residual bins.
    if open_bins_count > 0 {
        let mean_r = mean_residual;
        if (bin_residual as f64) < mean_r {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (spread load);
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; allow early.
        score += 18.0 + 40.0 * progress;
        // But if it's a big item and nothing fits well, new bin is okay.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits via a smooth polynomial shaping of post-residual.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Non-linear coupling: small post-residuals get extra reward, stronger late in stream.
    let tightness = (-norm_pr * 6.0).exp();
    score -= 12.0 * tightness * (0.5 + progress);

    // Dead-space penalty: residuals too small for any plausible item (1..=100) are wasted.
    let dead = if next_item_size > 0 {
        (next_item_size as f64 - pr).max(0.0) / cap
    } else {
        norm_pr
    };
    score += 8.0 * dead * dead * cap;

    // Last-chance bonus: strongly favor using the only bin that fits, smoothly.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Scarcity coupling: fewer open bins relative to stream length favors consolidation.
    let scarcity = (open_bins_count as f64 / (1.0 + progress * 10.0)).ln().max(0.0);
    score += 0.5 * scarcity * norm_pr * cap;

    // Mean-residual alignment: prefer bins near the mean residual (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 5.0 * (-gap * 4.0).exp();
    }

    // New-bin candidate: penalize mildly so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (1.0 - progress) + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 8 classes.
    let class = (post_residual * 8 / bin_capacity) as i64; // 0..7
    // Dead-space classes: tiny leftovers (class 0-1) are nearly useless -> penalize.
    score += match class {
        0 => 6.0,
        1 => 3.0,
        2 => 0.5,
        3 => -0.5,
        4 => -1.0,
        _ => -1.5,
    } as f64;

    // Perfect / near-perfect fits are golden.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Lookahead harmony: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: strong reward, scaled by tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 4.0 + 6.0 * tightness;
        } else {
            // Next item would be blocked: penalize proportionally to how close it is.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / bin_capacity as f64) * 8.0;
            // Modulo harmony: leftover divisible by common item sizes stays reusable.
            let pr = post_residual;
            if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
                score -= 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad class.
    if fitting_bins_count == 1 {
        if class <= 1 && post_residual > 0 {
            score += 5.0;
        } else {
            score -= 3.0;
        }
    }

    // New-bin candidate handling: empty bin has high base residual; only prefer it
    // when current placement would strand a lot of space and many bins are open.
    if bin_residual == bin_capacity {
        let stranded = post_residual as f64; // = capacity - item for new-bin call
        if stranded as u32 <= bin_capacity / 4 {
            score -= 10.0; // big item into fresh bin is fine
        } else if open_bins_count > 2 && class <= 1 {
            score -= 6.0; // escape hatch: avoid wrecking an open bin
        } else {
            score += 8.0; // prefer existing bins by default
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;
    // Slight drift with stream progress toward tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residuals are poison.
    if post_residual > 0 {
        // Dead space severity: inverse gap, amplified quadratically.
        let gap = post_residual as f64;
        let dead_severity = (bin_capacity as f64 - gap).max(1.0) / bin_capacity as f64;
        score += 12.0 * dead_severity * dead_severity * (gap.min(20.0) as f64).recip().min(1.0) * 20.0;
        // Penalize gaps too small for the lookahead item (k=2 lookahead waste).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to item size (waste ratio view).
    let waste_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += 6.0 * waste_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage opening another,
    // encourage consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure,
        // but relax when this bin would otherwise leave huge dead space elsewhere.
        let best_existing_gain = (mean_residual - post_residual as f64).max(0.0);
        score += 20.0 + pressure - 3.0 * best_existing_gain;
    } else {
        // Slight bonus for using existing bins under pressure.
        score -= 0.5 * pressure;
    }

    // Prefer bins below mean residual when residuals are tight (balance avoidance of many half-empty bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and next_item_size (the next item fills this bin's remaining space).
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        let diff = (pr - ns).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-step match: next item exactly seals this bin
        } else if ns <= pr {
            // next item fits here: reward proportionally to how well it fills
            let fill_ratio = ns / pr.max(1.0);
            score -= 40.0 * fill_ratio;
        } else {
            // next item cannot fit in the residual: penalize dead space
            score += 15.0 + diff * 0.3;
        }
    }

    // Penalize residuals that are awkwardly small (likely dead space),
    // but only mildly when this bin is the last chance to fit the item.
    if post_residual < 10 {
        score += 25.0;
        if fitting_bins_count == 1 {
            score -= 30.0; // forced placement is better than opening a bin
        }
    }

    // Last-chance bonus: strongly prefer using the only bin that fits,
    // avoiding a fresh bin for an item that barely fits elsewhere.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // (low mean residual relative to item needs) or late in the stream.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / mean_residual.max(1.0);
        if pressure > 0.8 || open_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 35.0 + 20.0 * pressure; // keep using existing bins
        }
    }

    // Mild reward for leaving residuals that stay "usable" (>= next small sizes)
    if post_residual >= 50 {
        score -= 5.0;
    }

    // Slight preference for fuller bins overall (relative to mean residual)
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    score += 0.3 * pr * pr / cap ;
    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 6 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0 ;
    } else if post_residual <= 12 && (post_residual as f64) < mean_residual * 0.6 {
        score -= 20.0 ;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            // dead-space penalty grows with slack relative to mean residual
            let dead = (slack / mean_residual.max(1.0)) * 6.0 ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity - dead ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            let progress = step_index as f64 / total_items . max (1) as f64 ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) ;
        }
    }
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity . max (1) as f64 ;
        score += 30.0 + 40.0 * (1.0 - tightness) ;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0 ;
        }
        if item_size * 2 >= bin_capacity {
            score -= 20.0 ;
        }
        // late in the stream, opening fresh bins is cheaper
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        if progress > 0.7 {
            score -= 10.0 * progress ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny slivers
    // that are likely dead space relative to the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Fit quality relative to bin: fraction of bin filled by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
        // If next item exactly fills the post-residual, big bonus.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when open bins are crowded and residual is fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so full bins are preferred over opening new ones.
        score += 20.0;
        // But if mean residual is small (bins nearly full), opening a new bin
        // becomes attractive.
        score -= 1.5 * (bin_capacity as f64 - mean_residual);
        // Penalize opening new bins when plenty of bins can already fit the item.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0);
        }
    }

    // Prefer bins whose residual is close to the item size (minimize waste gap).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * gap;

    // Time horizon: early in the stream, be conservative with new bins;
    // later, allow tighter packing decisions to matter more.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 5.0 * progress * fill_ratio;

    // Many open bins: encourage consolidating into existing ones.
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with non-linear shaping
    let mut score = (norm_pr * norm_pr) * cap * 0.5 + norm_pr * cap * 0.5;

    // Smooth non-linear coupling with stream progress:
    // early on, tolerate slack; late, penalize dead space quadratically
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits more as stream progresses (cubic interaction term)
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * cap * (0.2 + 0.6 * progress);

    // Penalize unusable dead space: residual too small for the smallest plausible item (1)
    // smooth penalty when post_residual is tiny relative to capacity
    let dead = (1.0 - norm_pr * 10.0).max(0.0);
    score += dead * dead * cap * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 2.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == cap as u32;
    if is_new_bin {
        // prefer new bin if mean residual across open bins is low (fragmented bins)
        let fragmentation = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (1.5 - 1.2 * fragmentation * fragmentation) + 10.0 * (1.0 - progress);
        // lookahead: if next item fits in the fresh bin after this one, favor opening
        if next_item_size as f64 <= pr {
            score -= cap * 0.8;
        }
    } else {
        // lookahead coupling: reward bins whose post-residual can host next item
        if next_item_size > 0 && post_residual >= next_item_size {
            let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= fit_quality * cap * (0.3 + 0.4 * progress);
        }
        // slight preference for bins with residual below mean (consolidate slack)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * dev * cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Penalize dead space quadratically, but with harmonic-class modulation
    score += frac * frac * 30.0;

    // Class A: post_residual in [1,9] -> tiny unusable sliver, heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Class B: perfect fit (post_residual == 0) -> big reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo classes on post_residual: residuals divisible by common item
    // sizes (10/20/25/50) are reusable by future items -> reward them
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            // harmonic class of the double-fit leftover
            if npost % 10 == 0 {
                score -= 12.0;
            }
            score -= (npost as f64 / cap) * 10.0;
        } else {
            // next item cannot use this bin's leftover: penalize tight leftovers
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling existing bins when many are open and mean residual is high
    if open_bins_count > 2 && mean_residual > (item_size as f64 + 5.0) {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless residual would be
    // well-used by the next item (lookahead justifies it)
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
