    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).min(1.0);
        score += 30.0 - 20.0 * fragmentation - 10.0 * progress;
