pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residues 0 (perfect) and small useful leftovers get bonuses.
        let class_bonus: f64 = match class {
            0 => 12.0,
            1..=3 => 4.0,
            4..=7 => 0.0,
            _ => -3.0,
        };
        score -= class_bonus;

        // Harmonic divisor check: can pr host a "typical" next item?
        if next_item_size > 0 && next_item_size <= pr {
            score -= 8.0;
            // Exact chain fit: post_residual % next_item_size == 0 is ideal
            if pr % next_item_size == 0 {
                score -= 10.0;
            } else {
                let rem = (pr % next_item_size) as f64;
                score -= 6.0 * (1.0 - rem / next_item_size as f64);
            }
        } else if next_item_size > pr && pr > 0 {
            // Dead space relative to lookahead: penalize proportionally
            score += 4.0 * (next_item_size as f64 - pr as f64) / bin_capacity as f64 * 10.0;
        }
    } else {
        // Perfect fill
        score -= 25.0;
    }

    // Integer-division threshold on post_residual: leftover > capacity/2 is
    // still flexible; leftover in (0, capacity/4] is risky dead space.
    if pr > 0 && pr <= bin_capacity / 4 {
        score += 6.0;
    } else if pr > bin_capacity / 2 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer tight fits generally: reward small post_residual relative to item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 1000.0 - pressure * 500.0 - progress * 200.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable for future
    // items (min item size 1, but typical items are large), so penalize them hard.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny dead space: worst outcome
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward closing the bin exactly
    }

    // Reward tight fits relative to residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but never so strongly that dead space is accepted.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: keep it attractive only when no open bin
    // offers a decent fit; penalize slightly so existing bins win ties.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If the next item is large and this item leaves a bad gap elsewhere,
        // opening fresh is reasonable: dampen the penalty.
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 0.9 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover is truly dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., fuller bins) to consolidate load.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match: strong bonus
        if diff == 0.0 {
            score -= 40.0;
        } else {
            score += diff * 0.6; // penalize mismatch
        }
        // If next item fits exactly or well in the residual, slight reward
        if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item cannot fit in this bin after placement: dead space risk
            score += 4.0;
        }
    }

    // Penalize large dead space relative to capacity
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 15.0;

    // Compare against mean residual: prefer bins with smaller residual (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless everything else is bad
    if bin_residual == bin_capacity {
        score += 10.0;
        // If lookahead shows next item is large, opening fresh bin may be OK
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Slight preference late in stream to consolidate
    let progress = step_index as f64 / total_items as f64;
    score += dead * progress * 5.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    // quadratic dead-space penalty, slightly stronger for large residuals
    score += 0.35 * pr * pr / cap ;
    if post_residual == 0 { score -= 1000.0 ; }
    else if post_residual <= 6 { score -= 50.0 + (6 - post_residual) as f64 * 10.0 ; }
    else if post_residual <= 12 && (post_residual as f64) < mean_residual * 0.6 { score -= 20.0 ; }
    // single lookahead block (deduplicated from parent)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            let progress = step_index as f64 / total_items . max (1) as f64 ;
            // penalize wasted space more aggressively early in the stream
            score += waste * (1.8 + (1.0 - progress) * 2.0) ;
        }
    }
    // new-bin candidate handling
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity . max (1) as f64 ;
        score += 30.0 + 40.0 * (1.0 - tightness) ;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 25.0 ; }
        if item_size * 2 >= bin_capacity { score -= 20.0 ; }
        // discourage opening a new bin when open bins are abundant and still roomy
        if open_bins_count > 4 && (bin_residual as f64) > mean_residual * 1.5 { score += 15.0 ; }
    }
    // mild compaction pressure: prefer bins whose residual is already below average
    if post_residual > 0 && (post_residual as f64) < mean_residual {
        score -= 6.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 range).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use the leftover: penalize proportionally.
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins that are already mostly full.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Late in the stream, be more aggressive about closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * fill_ratio;

    // Relative to the mean residual: prefer bins with less residual than average.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Many open bins: discourage spreading; prefer tighter bins.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        // New bin baseline: slightly above typical good-fit scores so tight fits win,
        // but below scores of very poor fits into open bins.
        score = 30.0 + bad_fit * 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pairing potential in a fresh bin.
            score -= 6.0;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
