    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog_poly = 0.5 + 0.5 * progress;
    score += (norm_pr * norm_pr) * cap * (0.25 + 0.75 * prog_poly);

    // Reward tight fits, stronger later in the stream (smooth cubic term)
    let tight = 1.0 - norm_pr;
    score -= tight * tight * tight * (item_size as f64) * (0.6 + 0.8 * progress);

    // Penalize dead space relative to mean residual (quadratic divergence)
    let dev = norm_pr - (mean_residual / cap);
    score += dev * dev * cap * 0.5;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 12.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Mild pressure on many open bins early, encouraging consolidation
    score += (open_bins_count as f64).sqrt() * 1.5 * (1.0 - progress);

    // New-bin candidate: penalize unless current residual is small (poor fit elsewhere)
    if bin_residual == bin_capacity {
        score += 20.0 - 18.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits via a smooth polynomial shaping of post-residual.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Non-linear coupling: small post-residuals get extra reward, stronger late in stream.
    let tightness = (-norm_pr * 6.0).exp();
    score -= 12.0 * tightness * (0.5 + progress);

    // Exact-fill jackpot: residual fully consumed is near-optimal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 6 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0;
    }

    // Dead-space penalty: residuals too small for any plausible item (1..=100) are wasted.
    let dead = if next_item_size > 0 {
        (next_item_size as f64 - pr).max(0.0) / cap
    } else {
        norm_pr
    };
    score += 8.0 * dead * dead * cap;

    // Last-chance bonus: strongly favor using the only bin that fits, smoothly.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Scarcity coupling: fewer open bins relative to stream length favors consolidation.
    let scarcity = (open_bins_count as f64 / (1.0 + progress * 10.0)).ln().max(0.0);
    score += 0.5 * scarcity * norm_pr * cap;

    // Mean-residual alignment: prefer bins near the mean residual (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // Lookahead: chain the next item into the leftover space.
    if next_item_size > 0 {
        if pr == next_item_size as f64 {
            score -= 220.0;
        } else if pr > next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 };
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 };
            let lone = if fitting_bins_count <= 1 { 8.0 } else { 0.0 };
            score -= 40.0 - slack.min(40.0) + chain_bonus + stranded + lone;
        } else {
            let waste = next_item_size as f64 - pr;
            score += waste * (1.5 + (1.0 - progress) * 1.5);
        }
        let gap = ((pr - next_item_size as f64).abs() / cap).exp();
        score -= 5.0 * (-gap * 4.0).exp();
    }

    // New-bin candidate: penalize so it wins only when fits are poor;
    // large items justify fresh bins more readily.
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / cap.max(1.0);
        let mut new_pen = 30.0 + 40.0 * (1.0 - tight);
        if next_item_size > 0 && pr >= next_item_size as f64 {
            new_pen -= 25.0;
        }
        if item_size * 2 >= bin_capacity {
            new_pen -= 20.0;
        }
        score += new_pen + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover space by integer division.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual in (0,10] -> nearly perfect fit, heavily reward.
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    } else if post_residual <= 35 {
        score += 5.0;
    } else if post_residual <= 50 {
        score += 10.0;
    }

    // Modulo coupling: leftovers that are multiples of small harmonic units (10, 20, 25)
    // are more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer bins whose leftover after the next item stays in a good class.
            score -= 20.0 * (1.0 - slack / cap);
            if slack <= 10.0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: penalize wasting a tight residual.
            if post_residual < 20 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it is only
    // chosen when open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins close to the mean (balanced packing),
    // avoid outliers creating fragmented space.
    score += 0.3 * (pr - mean_residual).abs();

    // Prefer filling bins that are already mostly full (tight fits).
    score -= 10.0 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
