    if bin_residual == bin_capacity {
        let tight = item_size as f64 / bin_capacity.max(1) as f64;
        score += 30.0 + 40.0 * (1.0 - tight);
        if next_item_size > 0 && post_residual >= next_item_size as f64 { score -= 25.0; }
        if item_size * 2 >= bin_capacity { score -= 20.0; }
