    // Lookahead coupling: reward if next item fits the post-residual exactly
    // or nearly; penalize if lookahead forces a new bin anyway.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // chains perfectly
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - ((post_residual - next_item_size) as f64) / 40.0);
        } else {
            score += 8.0; // next item won't fit here regardless
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
