    // bins with below-average residual (consolidation effect).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * dev;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when current fit is very poor or no real alternatives.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // Penalize opening a new bin unless it creates a near-perfect packing.
        if fit_quality < 0.15 {
            score -= 5.0; // excellent fit, allow the new bin
        } else {
            score += 10.0 + 15.0 * fit_quality * horizon;
        }
        // With many open bins and high mean residual, opening new bins is wasteful.
        if open_bins_count > 2 && mean_residual > 30.0 {
            score += 8.0;
        }
    }

    // Mild time-decay noise-free tiebreak: prefer earlier-opened (lower residual
    // variance) bins as stream ends; approximate via progress-weighted residual.
    score += 0.02 * (bin_residual as f64) * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;

    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && (post_residual as f64) < (item_size as f64 * 0.35) . min (30.0) { 120.0 } else { 0.0 } ;
        let crowd = if open_bins_count == 0 { - 200.0 } else if open_bins_count > 6 { 20.0 } else { 60.0 } ;
        score = 100.0 + crowd - bad_fit ;
        // refined new-bin logic: tightness-aware penalty, borrow from best
        let tightness = item_size as f64 / cap . max (1.0) ;
        score += 30.0 + 40.0 * (1.0 - tightness) ;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 25.0 ; }
        if item_size * 2 >= bin_capacity { score -= 20.0 ; }
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score -= (1.0 - progress) * 25.0 ;
        score -= 2.0 * open_bins_count as f64 ;
        if next_item_size >= 60 { score -= 15.0 ; }
        if mean_residual > item_size as f64 * 2.5 && open_bins_count > 3 {
            score += (mean_residual - item_size as f64 * 2.5) * 0.4 ;
        }
    }

    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 6 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0 ;
    } else if post_residual <= 12 && (post_residual as f64) < mean_residual * 0.6 {
        score -= 20.0 ;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            let progress = step_index as f64 / total_items . max (1) as f64 ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) ;
        }
    }

    score += 0.5 * (pr - mean_residual) ;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 ;
    } else if fitting_bins_count == 2 && bin_residual < bin_capacity {
        score -= 25.0 ;
    }

    if bin_residual != bin_capacity {
        let gap_dev = (pr - mean_residual . max (1.0)) . abs () ;
        if gap_dev < 5.0 { score -= 4.0 ; }
        else if gap_dev > 30.0 { score += 3.0 ; }
        if pr > 10.0 && pr < 25.0 { score += (25.0 - pr) * 0.6 ; }
    }

    score += 0.3 * pr * pr / cap ;
    let score = score * 0.95 + ((open_bins_count as f64 * 1.5) as f64) * 0.05 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with progress-dependent curvature
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr) * cap * 0.01;

    // Non-linear coupling: reward small post_residual more strongly as stream progresses
    let tight = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 10.0 * tight.powi(3) * (0.5 + progress);

    // Dead-space penalty: residuals too small to fit typical future items
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr as f64) * (1.0 + progress);
    }

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer opening a fresh bin when existing fits are poor
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score = waste * (0.6 + 0.4 * progress) - 3.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 1.0;
        }
    }

    // Lookahead synergy: reward leaving room for the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 2.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
