pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core).
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: capacity fractions define desirability tiers.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity remaining

    // Dead-space classes: residuals that can't fit typical small items (1..=10) are worst.
    if post_residual < 10 {
        score -= 60.0; // nearly perfect fit, strongly reward
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 35 {
        score -= 8.0;
    } else if post_residual <= 50 {
        score += 5.0;
    } else {
        score += 12.0; // more than half empty after placement: wasteful
    }

    // Modulo-10 harmonic class: residuals divisible by 10 align with item granularity,
    // making future packing more likely.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 15.0 * (1.0 - gap as f64 / c);
        } else {
            // next item won't fit here; penalize leaving a large unusable remainder
            score += 4.0 * (next_item_size as f64 - pr).min(30.0) / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad split
    // unless the fit is genuinely tight.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: proportional to stream progress and open bins.
        score = c * 0.85;
        // Late in stream or few bins: opening is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
        // If many open bins with large mean residual, prefer reusing them.
        score += 0.35 * mean_residual;
        // Perfect lookahead into fresh bin: next item large and known -> slight discount.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild preference to consolidate: fewer open bins -> favor filling existing ones.
    if open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small to ever hold the
    // minimum item (1..MIN_ITEM) are pure waste -> heavy penalty.
    const MIN_ITEM: u32 = 1;
    if post_residual > 0 && post_residual < MIN_ITEM {
        score += 500.0;
    }

    // Small unusable gaps: penalize residuals that no plausible future item
    // (typical sizes) can fill; scale penalty by how "hopeless" the gap is.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    } else if post_residual <= 25 {
        // moderately awkward gap
        score += (26.0 - post_residual as f64) * 1.5;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Penalize if the gap is just barely too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // the more bins already open, the more we favor compacting into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (10.0 + 20.0 * progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize opening a new bin unless the fit is
        // unusually tight (large item) or existing bins are badly fragmented.
        score += 40.0 + 30.0 * progress;
        if item_size >= bin_capacity / 2 {
            score -= 50.0;
        }
        // If existing bins are highly fragmented (low mean residual relative
        // to item), opening fresh is more acceptable.
        if mean_residual < item_size as f64 * 1.2 && mean_residual > 0.0 {
            score -= 25.0;
        }
    }

    // Mild bonus for tight fits relative to residual (fill ratio).
    if bin_residual > 0 {
        score -= (item_size as f64 / bin_residual as f64) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
