    // Relative-to-mean residual: prefer bins whose post_residual deviates favorably.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when a reasonable fit exists among open bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if next item also fits well after this item.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let chain_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score = 100.0 - 20.0 * chain_fill;
        } else {
            score = 120.0;
        }
    }

    // Late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
