        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins that become nearly full.
    let fill_frac = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * fill_frac * fill_frac;

    // Lookahead: reward if the next item can fit in the post residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= post_residual as f64 {
            // Perfect chaining: next item exactly fills leftover space.
            let chain_tight = 1.0 - (post_residual as f64 - ns) / cap;
            score -= 18.0 * chain_tight;
        } else {
            // Penalize leaving residue that the next item cannot use,
            // scaled by how dead the space is relative to smallest useful size.
            let dead = (post_residual as f64) / cap;
            score += 25.0 * dead * dead;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 30.0 * (item_size as f64 / cap);
    }

    // New-bin candidate handling: penalize opening a fresh bin when good fits exist,
    // unless the item is huge and would waste little space.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 60.0; // base reluctance to open new bin
        score -= 0.9 * waste; // large items justify new bins
        // Late in the stream, prefer consolidating into open bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * t;
        // If many bins are open with slack, discourage another bin.
        if mean_residual > (item_size as f64) {
            score += 15.0;
        }
    }

    // Mild preference for bins below mean residual (balance load, keep big holes alive).
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.08 * diff;

    // Early stream: keep some big-residual bins alive for future awkward items.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - t) * ((post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // later in the stream, tighter fills matter more (dead space is costlier)
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += poly * cap * 0.35;

    // Reward near-perfect fits smoothly (post_residual close to 0)
    let perfect = (1.0 - norm_pr).powi(3);
    score -= perfect * cap * 0.25 * (0.5 + progress);

    // Lookahead: reward bins whose post-residual can host the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - nxt) / cap;
        let kernel = (-gap * gap * 8.0).exp();
        score -= kernel * cap * 0.30;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 0.5 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    let frag = norm_pr * (open_bins_count as f64).ln1p();
    score += frag * cap * 0.05;

    // Alignment with mean residual: bins close to the mean are "typical" targets
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * cap * 0.08;

    // New-bin candidate: keep it neutral-to-slightly-unattractive unless residual is tiny
    if bin_residual == bin_capacity {
        score += cap * 0.15 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction classes (integer division thresholds).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class index: 0 = perfectly full, 1 = tiny dead space, ... larger = roomy
    let class = (post_residual / (bin_capacity / 8).max(1)) as i32; // eighth-capacity classes

    // Reward small dead space non-linearly (quadratic penalty on residual),
    // but treat the "harmonic" classes {0, 25, 50} as especially valuable
    // since they pair well with common item sizes.
    let harmonic_bonus: f64 = match post_residual {
        0 => 40.0,                      // perfect fit
        25 | 50 | 75 => 22.0,           // quarter-class harmonics
        _ => {
            if post_residual <= 10 { 15.0 }
