    score += 0.05 * post * post / cap;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: mild reward scaled
            // by how harmonically the chain closes
            let chain_post = post_residual - next_item_size;
            if chain_post == 0 { score -= 28.0; }
            else if chain_post < 10 { score -= 12.0; }
            else { score -= 5.0 * (1.0 - chain_post as f64 / cap); }
        } else {
            // next item won't fit here: penalize slightly, more if this bin
            // would end up with awkward leftover class
            score += 6.0 + 0.1 * post;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent (harmonic) fit.
    if bin_residual == bin_capacity {
