        if fitting_bins_count == 0 { score -= 40.0; }
        // If mean residual across open bins is small, new bin is justified
        score -= (mean_residual / cap).min(1.0) * 5.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
