    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 4.0; // gap too small for any item (min size 1..100, but small gaps waste)
    }
    if pr > 0.0 && pr < 25.0 {
        score += (25.0 - pr) * 0.8; // soft penalty tapering
