        score += 8.0 + pressure * 2.0;
    } else {
        score -= pressure.min(10.0) * 0.3;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Mean residual coupling: bins far below mean residual are better consolidation targets
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
