        score -= 10.0;
    }

    // Penalize bins with residuals far from mean (avoid fragmenting outlier bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; a good match in an existing bin should beat it.
        score = 45.0 + 0.3 * (item_size as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
