    // Time horizon: early in stream, opening new bins is cheap (exploration);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 40.0 * (1.0 - progress) * (1.0 - progress);
