    }

    // refined compaction term: reward tight fits scaled by scarcity of fitting bins
    let fit_tightness = 1.0 - pr / cap;
    score -= fit_tightness * (8.0 + 10.0 * (1.0 - progress));

    let score = score * 0.70 + pr * 0.30;
    score
}

