    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        score += 15.0 * ((x - nx).abs() - x.max(0.0)).max(0.0);
        score -= 10.0 * (1.0 - ((x - nx).abs() / cap).min(1.0)) * nx;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).sqrt() * 0.5 * progress;

    // Encourage opening fresh bins early when fit is poor
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress) * (1.0 - x) * cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of common
    // item sizes (or capacity fractions) are more reusable.
    let pr = post_residual;
    let class: u32 = if pr == 0 {
        0
    } else if pr <= 5 {
        1
    } else if pr % 10 == 0 {
        2
    } else if pr % 5 == 0 {
        3
    } else {
        4
    };
    score += match class { 0 => -14.0, 1 => 6.0, 2 => -6.0, 3 => -2.0, _ => 3.0 };

    // Dead-space penalty grows superlinearly for small unusable residuals.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.5;
    }

    // Lookahead harmony: can next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 16.0; // perfect pairing
        } else if next_item_size < pr {
            let leftover = pr - next_item_size;
            score -= 6.0 - (leftover as f64).min(6.0);
            if leftover % 10 == 0 { score -= 4.0; }
        } else {
            score += 2.0; // next item can't use this bin anyway
        }
    } else {
        // Last item: prefer emptying bins entirely.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual < 10 { score += 8.0; } // still penalize dead space
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += (bin_residual as f64 / cap) * 4.0;

    // Early in the stream, allow more bins to spread large items; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Slight pull toward mean residual to keep bin states balanced.
    score += (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || (post_residual as f64) > 0.55 * cap {
            score -= 8.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

