        score += 35.0;
        // Reduce penalty if item is large relative to mean residual (poor fits likely).
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        // If the next item would fit in the fresh bin's post space, new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Existing bin that leaves space for the lookahead item is valuable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size > 0 {
            score += 6.0; // blocks the next item
        }
