            score -= 220.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 };
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 };
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 };
            score -= 40.0 - slack.min(40.0) + chain_bonus + stranded + scarcity;
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += waste * (1.5 + (1.0 - progress) * 1.5);
        }

        // gap shaping: reward near-exact future fits, mildly punish mid gaps
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0;
            } else if gap <= 12 {
                score += (13 - gap as i32) as f64 * 4.0;
            } else {
                score -= 5.0;
            }
        }

        // two-item lookahead: residual that fits next item plus a small extra
        // is a near-perfect chain; reward it to reduce dead space.
        let rem = post_residual.saturating_sub(next_item_size);
        if rem > 0 && rem <= item_size.max(1) {
            score -= 15.0;
        }
    }

    // Blend toward pure post-residual compaction
    let score = score * 0.70 + pr * 0.30;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth interaction: tight fits rewarded more strongly as stream progresses.
    let tightness = 1.0 - norm_pr * norm_pr; // high for small post_residual
    let progress_coupling = 0.5 + 1.5 * progress * progress;
    score -= 12.0 * tightness * progress_coupling;

    // Penalize large dead space non-linearly (cubic), amplified late in stream.
    let dead = norm_pr * norm_pr * norm_pr;
    score += 8.0 * dead * (1.0 + 2.0 * progress);

    // Perfect-fit bonus (smooth exponential-like via polynomial of residual).
    if post_residual == 0 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving space that still fits next item,
    // penalize residual that is too small to be useful.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let fit_margin = (pr - ni) / cap;
            score -= 6.0 * (1.0 - fit_margin * fit_margin) * (0.5 + progress);
        } else {
            let gap = (ni - pr) / cap;
            score += 5.0 * gap * gap * (1.0 + progress);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 2.0 * progress);
    }

    // Mild penalty when many bins are open and this bin is far below mean residual
    // (encourages consolidating residual mass, smooth quadratic form).
    let dev = (pr - mean_residual) / cap;
    if dev > 0.0 {
        score += 4.0 * dev * dev * (0.5 + open_bins_count as f64 * 0.05);
    }

    // New-bin candidate: penalize opening a new bin unless residual is very tight
    // elsewhere; smooth ramp based on how full current bins are on average.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        score += 18.0 - 30.0 * mean_fill * mean_fill;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
