        score += 25.0;
        // if many fitting bins exist, opening new bin is wasteful
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
        // if mean residual across open bins is large, prefer using them
        score += mean_residual * 0.3;
        // late in stream, avoid opening new bins more aggressively
        score += 10.0 * progress;
        // if item is small, new bin wastes lots of capacity
        score += (bin_capacity - item_size) as f64 * 0.1;
    }

    // Mild penalty for leaving post_residual in "unusable" zone (too small for min item 1..10 typical)
    if post_residual > 0 && post_residual < 5 && bin_residual < bin_capacity {
        score += 2.0;
    }

    // Slight preference for bins with below-mean residual (consolidate fullness)
    score += ((mean_residual - bin_residual as f64).abs()) * 0.02;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
