    score += 12.0 * norm_pr * norm_pr * (1.0 + progress_coupling);
    score -= 8.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward residual that can fit next item, penalize near-miss waste
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxt - pr) / cap;
            score += 10.0 * miss * miss;
