pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets over capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fit (residual < 10% of capacity) -> strongly reward.
    if pr < 0.10 * cap {
        score -= 25.0;
    }
    // Class B: dead zone (residual just above 10%..20%) -> penalize unusable slivers.
    else if pr < 0.20 * cap {
        score += 8.0;
    }
    // Class C: golden residual (>= 50% capacity) -> mild reward, keeps big space alive.
    else if pr >= 0.50 * cap {
        score -= 4.0;
    }

    // Integer-division harmonic classes on post_residual (quantized to 10s).
    let class = post_residual / 10;
    match class {
        0 => score -= 20.0,            // 0..9 : perfect seal
        1 => score += 6.0,             // 10..19 : awkward sliver
        2 => score += 3.0,             // 20..29 : moderately awkward
        3 | 4 => score -= 2.0,         // 30..49 : usable mid range
        5 | 6 => score -= 6.0,         // 50..69 : valuable space
        _ => score -= 1.0,             // 70+ : large residual
    }

    // Lookahead harmonic coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Harmonic class match on tens: next item lands in same quantized class.
            let nclass = next_item_size / 10;
            if nclass == class && class > 0 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here: if this residual is a dead sliver, penalize.
            if pr < 0.20 * cap {
                score += 12.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish score = capacity; make it attractive
    // only when current bins are fragmented (low mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = 1.0 - (mean_residual / cap);
        // Prefer new bin when open bins are small-residual and it's early.
        score = cap * (0.6 + 0.4 * fragmentation) - 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score = -100.0; // must open first bin
        }
    }

    // Mild preference to consolidate across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
