}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small dead space penalty: residuals that can never fit even the smallest
    // future item (assume min size ~1, but tiny residuals < 10 are near-worthless).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        }
        // Perfect pairing: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving a residual that is too small for the next item
        // (likely wasted dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // New-bin candidate handling: mildly penalize opening a new bin so that
    // decent fits into open bins win, but allow it when the fit is bad
    // (large leftover waste) or when many bins are already open.
    if bin_residual == bin_capacity {
        // Base new-bin cost, decreasing as existing bins become crowded.
        let crowding = mean_residual / bin_capacity as f64;
        score += 15.0 + 20.0 * (1.0 - crowding);
        // If the item would leave big waste in any existing bin, new bin is fine.
        if post_residual < item_size / 2 {
