            0.0
        };
        score += 10.0 * progress;
    }

    // Global pressure: when many bins are open, prefer filling existing ones.
    score += 0.5 * open_bins_count as f64;

    // Slight preference for bins with above-average residual when fit is loose.
    if fit_ratio < 0.5 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
