    let new_bin_bonus = 15.0 * progress;
    score -= new_bin_bonus;

    // Global state: many open bins with high mean residual suggests
    // fragmentation; prefer filling existing bins harder.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 5.0 + 0.05 * mean_residual;
    }

    // Penalize opening a new bin when existing bins fit well
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // Pairing large items together in fresh bins can be good.
            score -= 8.0;
        }
    }

    // Small coupling: item size relative to capacity.
    let size_frac = item_size as f64 / bin_capacity as f64;
    score -= 4.0 * size_frac * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post-residual, with polynomial shaping
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Smooth stream-progress coupling: later in stream, tolerate larger post residual less
    score += 8.0 * progress * norm_post * norm_post;
    score -= 6.0 * (1.0 - progress) * norm_post;

    // Dead-space penalty: quadratic in unusable space (post_residual below smallest possible item ~1)
    let dead = (norm_post).max(0.0);
    score += 4.0 * dead * dead * (1.0 - dead);

    // Last-chance bin bonus: only fitting bin => strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate: only open a new bin when post-residual is large (roomy) and few alternatives
    if bin_residual == bin_capacity {
        let roominess = post / cap; // = 1.0 - item_size/cap
        score = cap - (roominess * roominess) * 30.0 + 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let fit_quality = 1.0 - (post - next) / cap;
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            score += 2.0 * (next - post) / cap;
        }
    }

    // Mean residual interaction: prefer bins deviating from mean to preserve diversity
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact halves/quarters are valuable slots
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, dead space minimal
    } else {
        // penalize dead space that cannot plausibly be reused
        let frac = pr as f64 / cap;
        if pr % 50 == 0 {
            score -= 15.0; // exact half-capacity slot: very reusable
        } else if pr % 25 == 0 {
            score -= 8.0;
        } else if pr % 10 == 0 {
            score -= 4.0;
        } else {
            score += frac * 40.0; // awkward remainder
        }
        // items 1..100: small residuals < 20 are often unusable
        if pr < 20 {
            score += (20 - pr) as f64 * 0.5;
        }
    }

    // Lookahead coupling: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // enables chaining
            // harmonic match bonus when post_residual is a near-multiple of next item
            let diff = post_residual - next_item_size;
            if diff <= 5 {
                score -= 10.0;
            }
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin anyway
        } else if crowded < 0.25 {
            score -= 10.0; // plenty of slack overall, spreading is fine
        } else {
            score += 15.0 + open_bins_count as f64 * 0.5; // prefer filling existing bins
        }
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10, or < next item) are heavily penalized.
    if post_residual > 0 {
        let unusable = post_residual < 10
            || (next_item_size > 0 && post_residual < next_item_size);
        if unusable {
            score += 40.0 + 2.0 * post_residual as f64;
        } else {
            // Reward usable leftovers, especially those that can host the lookahead item.
            score -= 6.0;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 10.0;
            }
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_frac;

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when item is huge relative to mean residual
    // or no reasonable open-bin fit exists.
    if bin_residual == bin_capacity {
        let desperate = mean_residual < item_size as f64 * 1.05
            || item_size > 70
            || (post_residual as f64) < mean_residual * 0.5;
        if desperate {
            score -= 30.0;
        } else {
            score += 20.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Late in the stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;

    // NEW-BIN CANDIDATE gating: prefer opening a fresh bin when no open bin
    // offers a tight fit, or when the item is large and fits would be sloppy.
    if bin_residual == bin_capacity {
        let residual_gap = (bin_residual - item_size) as f64 ;
        let decent_fit_exists = fitting_bins_count > 0 && residual_gap > 0.0 ;
        if decent_fit_exists && fitting_bins_count > 1 {
            // multiple fits exist -> new bin slightly penalized, tuned by gap tightness
            let tightness = 1.0 - (residual_gap / cap) ;
            score += 26.0 + 14.0 * (1.0 - tightness) ;
        } else if decent_fit_exists {
            // single sloppy fit: opening a new bin is attractive if the leftover
            // would be dead space unlikely to host next_item_size
            let next_fits_leftover = next_item_size > 0 && residual_gap >= next_item_size as f64 ;
            if !next_fits_leftover && residual_gap > 4.0 {
                score -= 12.0 + 0.4 * residual_gap . min (30.0) ;
            } else {
                score += 10.0 ;
            }
        }
        if pr > mean_residual { score -= 5.0 ; }
        score += progress * 10.0 ;
    }

    // quadratic compaction pressure
    score += 0.3 * pr * pr / cap ;

    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 6 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0 ;
    } else if post_residual <= 12 && pr < mean_residual * 0.6 {
        score -= 20.0 ;
    }

    // lookahead coupling with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 260.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) ;
        }
    }

    // dead-space ratio term: penalize residuals that are hard-to-fill windows
    let dead_window = pr > 0.0 && pr < 8.0 && (next_item_size as f64) > pr ;
    if dead_window { score += 15.0 * (8.0 - pr) / 8.0 ; }

    // mild scarcity bonus: when few bins can host the item, reward tight fits more
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0 ;
    }

    let score = score * 0.70 + pr * 0.30 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = (post_residual as f64 - next) / (bin_capacity as f64);
            // Exact match for next item => chain bonus.
            if gap == 0.0 {
                score -= 45.0;
            } else {
                score -= 25.0 * (1.0 - gap);
            }
        } else {
            // Next item cannot follow: penalize proportionally to wasted chain potential.
            let shortfall = (next - post_residual as f64) / (bin_capacity as f64);
            score += 18.0 * shortfall;
        }
    }

    // Relative to mean residual: prefer filling bins that are already below-mean
    // (consolidating waste), penalize draining above-mean bins into dead space.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 8.0 * dev;

    // Penalize creating tiny unusable slivers relative to smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest; slight penalty to spread out.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only open a new bin when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // If next item chains well into an empty bin, soften the cost.
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheaper (builds a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If few fitting bins and current residuals are large, new bin is more attractive.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild penalty for many open bins to discourage bin proliferation.
    score += 0.3 * (open_bins_count as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
