    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && (bin_residual as f64 - item_size as f64) > 0.0 ;
        if decent_fit_exists && fitting_bins_count > 1 {
            // penalize opening a new bin more strongly when many bins fit,
            // scaled by how tight those fits are
            score += 25.0 + (fitting_bins_count as f64).min(10.0) * 3.0 ;
        } else if decent_fit_exists {
            // only one candidate bin: opening fresh is cheaper, small penalty
            score += 6.0 ;
        }
        // late in stream, prefer consolidating into existing bins
        score += 10.0 + progress * 25.0 ;
        // if the new bin would leave a large residual vs. mean, discourage
        if pr > mean_residual * 1.2 { score -= 4.0 ; }
    }

    // quadratic residual pressure: strongly prefer compact bins
    score += 0.3 * pr * pr / cap ;

    if post_residual == 0 {
        score -= 1000.0 ;
    } else if post_residual <= 6 {
        score -= 50.0 + (6 - post_residual) as f64 * 10.0 ;
    } else if post_residual <= 14 && pr < mean_residual * 0.65 {
        score -= 22.0 ;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0 ;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) ;
        }
        // two-step lookahead: residual that fits next item tightly is gold
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size ;
            if gap == 0 {
                score -= 40.0 ;
            } else if gap <= 12 {
                score += (13 - gap as i32) as f64 * 4.0 ;
            } else {
                score -= 5.0 ;
            }
        }
    }

    // final blend: emphasize compaction a bit more than parent
    score * 0.72 + pr * 0.28
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of post-residual
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 0.5);

    // Penalize dead space that can't hold even the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // waste that blocks the next item
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else {
            let best_gap = (bin_residual as f64 - item_size as f64).abs();
            (best_gap / bin_capacity as f64).min(1.0)
        };
        // open new bin when few fitting bins or fits are bad, more likely late in stream
        score += 40.0 - 55.0 * poor_fit - 20.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing spacious bins
    if open_bins_count > 2 && mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual.max(1.0);
        score += 6.0 * (rel - 1.0).clamp(-1.0, 1.0);
    }

    // Time horizon: early stream, be conservative with near-perfect fits; late stream, pack tight
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if bin_residual == bin_capacity {
