            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            let progress = step_index as f64 / total_items . max (1) as f64 ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) ;
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size ;
        if gap == 0 {
            score -= 40.0 ;
        } else if gap <= 12 {
            score += (13 - gap as i32) as f64 * 4.0 ;
        } else {
            score -= 5.0 ;
        }
    }
    if post_residual > 0 {
        let frag = (post_residual as f64 / cap) ;
        if frag < 0.12 && next_item_size > post_residual {
            score += 15.0 * (0.12 - frag) * cap ;
        }
        let tightness = (item_size as f64 / bin_residual . max (1) as f64) ;
        if tightness > 0.85 { score -= 12.0 * (tightness - 0.85) ; }
        if post_residual < 20 && next_item_size > post_residual {
            score += (20 - post_residual) as f64 * 2.0 ;
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let after2 = post_residual - next_item_size ;
        if after2 >= item_size . min (next_item_size) { score -= 10.0 ; }
        if after2 > 0 && after2 <= 8 { score -= 8.0 ; }
    }
    if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0 ; }
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    if fitting_bins_count > 2 { score += 3.0 ; }
    if next_item_size > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.8 {
        score += 10.0 * (1.0 - progress) ;
    }
    let score = score * 0.70 + ((post_residual as f64) as f64) * 0.30 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: reward tight fits (low post_residual), with non-linear emphasis
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (dead space is costlier)
    let coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 0.5 + progress * progress;
    score *= coupling;

    // Penalize residuals that cannot fit the next item (smoothly)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = ((nx - pr).max(0.0)) / cap;
        score += 25.0 * gap * gap;
        // Reward residuals that exactly or nearly fit the next item
        let fit_gap = (pr - nx).abs() / cap;
        score -= 15.0 * (1.0 - fit_gap).max(0.0) * (1.0 - fit_gap);
    } else {
        // Last item: pure dead-space minimization
        score += 20.0 * norm_pr;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - progress + 0.3);
    }

    // Mildly discourage proliferation of open bins with large mean residual
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * (mean_residual / cap) * (mean_residual / cap);

    // New-bin candidate: penalize opening a fresh bin unless current residual is wasteful
    if bin_residual == bin_capacity {
        // Smooth threshold: opening a new bin is attractive when existing residuals are large
        let waste = mean_residual / cap;
        score = cap * (1.0 + 2.0 * progress) - 60.0 * waste * waste - 20.0 * norm_pr;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

