            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            // If next item would NOT fit here, keeping a large residual matters more.
            if next_item_size > post_residual && post_residual < next_item_size {
                score += 3.0 * (next_item_size - post_residual) as f64 / 10.0;
