        } else {
            // Next item can't use this bin's residual anyway: prefer tight fit now.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive if
    // all open bins are nearly full / fragmented.
    if bin_residual == bin_capacity {
        let mean_fill_gap = (mean_residual - pr) / cap;
        // Base cost of a new bin; discounted when open bins are very full.
        score = 0.35 * cap + 20.0 * mean_fill_gap.max(0.0);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0; // big next item: fresh bin may serve it well
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - pr / cap);

    // Slight preference to spread across bins when many are open and empty.
    if open_bins_count > 3 && pr > 3.0 * quarter {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": small post_residuals that no future item can use.
    // An empty gap is fine (new bin); a large gap is reusable; small gaps are waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 30.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 15.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 40.0;
    }

    // Reward tight fits generally (small waste relative to item size).
    score -= 25.0 / (1.0 + (post_residual as f64).max(1.0));

    // Dead-space check against lookahead: if next item can't use the gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0; // gap is exactly consumable by the next item
    }

    // Open-bin pressure: prefer consolidating into fewer bins early; late in the
    // stream, allow opening new bins since leftovers matter less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 1.5 * (1.0 - progress));

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when no open bin is a good fit,
    // i.e., when its residual (full capacity) beats mean residual usage poorly.
    if bin_residual == bin_capacity {
        // Baseline neutral-ish; slight penalty so tight fits win, but beats bad fits.
        score += 5.0 + mean_residual * 0.1;
    }

    // Prefer bins whose residual is below the mean (denser bins first).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

