    // Lookahead: if the next item cannot fit in post_residual, this placement
    // creates dead space relative to the lookahead horizon.
    if next_item_size > 0 && post_residual < next_item_size {
        // Penalty grows as the dead space becomes "useless" (small leftover).
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.8;
        // Very small leftovers are nearly unusable dead space.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // If the next item fits here after placement, reward chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Tight fit reward relative to current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Compare against mean residual: placing into an already-small bin
    // concentrates waste; prefer bins whose residual is near/below mean.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += ((bin_residual as f64) - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when the current item
    // is large and no good chaining is possible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = next_item_size == 0 || post_residual < next_item_size;
        if item_size >= 60 && poor_fit {
            score -= 15.0 + 10.0 * progress;
        } else {
            // Prefer reusing open bins otherwise.
            score += 35.0;
        }
    }

    // Mild late-stream pressure to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
