    // Time horizon: early in the stream, be conservative about fragmenting
    // space; late in the stream, just close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    // New-bin candidate handling: opening a new bin is only attractive when
