            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0;
            } else if gap <= 12 {
                score += (13 - gap as i32) as f64 * 4.0;
            } else {
                score -= 5.0;
            }
        }
        // anticipate pair: next item + a small companion fits remaining space
        if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next <= 10 {
                score -= 14.0;
            }
        }
    }

    // scarcity-aware compaction: fewer fitting bins -> prefer tight fits more strongly
    if fitting_bins_count <= 2 {
        score += pr * 0.1;
    }

    let score = score * 0.70 + pr * 0.30;
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
