        if progress > 0.7 { score += 14.0 * (progress - 0.7) / 0.3 ; }
    }

    // quadratic dead-space penalty, sharpened for small residuals
    score += 0.3 * pr * pr / cap ;
    if post_residual == 0 { score -= 1000.0 ; }
    else if post_residual <= 6 { score -= 50.0 + (6 - post_residual) as f64 * 10.0 ; }
    else if post_residual <= 12 && pr < mean_residual * 0.6 { score -= 20.0 ; }

    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 260.0 ; }
        else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            let chain_bonus = if slack <= 7.0 { 18.0 } else { 0.0 } ;
            let stranded = if slack > 10.0 && slack < 22.0 { 12.0 } else { 0.0 } ;
            let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 } ;
            score -= 40.0 - slack . min (40.0) + chain_bonus + stranded + scarcity ;
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            // waste hurts more early (long remaining stream) and when few bins fit next item
            let scarcity = if fitting_bins_count <= 1 { 1.6 } else { 1.0 } ;
            score += waste * (1.5 + (1.0 - progress) * 1.5) * scarcity ;
        }
        // lookahead two-step: reward residuals that can host next item with a small leftover
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size ;
            if gap == 0 { score -= 40.0 ; }
            else if gap <= 12 { score += (13 - gap as i32) as f64 * 4.0 ; }
            else { score -= 5.0 ; }
        }
    }

    // harmony term: prefer residuals close to the current mean (balanced packing)
    score += 0.05 * (pr - mean_residual) . abs () ;
    let score = score * 0.70 + pr * 0.30 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Harmonic class penalty: dead space in "awkward" residue classes (mod 10)
    // is harder to fill later; classes near 0 (perfect fit) are rewarded.
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.4;

    // Deeper harmonic coupling: penalize post_residual in the 1..9 band of any
    // decade (unusable slivers), reward exact-decade leftovers.
    if post_residual > 0 && post_residual % 10 != 0 {
        score += 2.0;
    }

    // Lookahead chaining: reward bins whose leftover can host the next item,
    // especially when the next item lands in a compatible residue class.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // leftover too small for the next item -> likely dead space
            score += 3.0 + 0.05 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins tighter than the fleet average (best-fit flavor).
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate penalty: opening a bin wastes capacity; make the
    // penalty grow over the stream so late poor fits are avoided, but allow
    // new bins when the leftover would be a clean harmonic class.
    if bin_residual == bin_capacity {
        let clean = if post_residual % 10 == 0 { 0.0 } else { 6.0 };
        score += 4.0 + 12.0 * progress + clean;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
