pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // another item (min item size 1, but practically < ~10) are pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver
        } else if post_residual < 20 {
            score += 15.0; // nearly unusable
        } else if post_residual < 35 {
            score += 4.0; // tight gap, hard to fill
        } else {
            // Larger usable gaps: mildly reward exact/large leftover utility
            score -= 2.0;
        }
    } else {
        // Perfect fit: strongly favored
        score -= 25.0;
    }

    // Reward tight fits: small post_residual relative to item size
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than opening yet another one.
    let open_pressure = (open_bins_count as f64) * 0.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open,
        // reward slightly when few bins exist (early stream).
        score += 12.0 + open_pressure;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        score -= open_pressure * 0.3;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin; finishing it off is good.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.2 * (res - mean_residual);
    }

    // Lookahead: if the next item fits exactly in the resulting post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual - next_item_size < 10 {
            score -= 8.0; // next item leaves only a sliver -> good chain
        }
    }
    // If next item would NOT fit here after placement, but would fit in
    // another bin, mildly discourage blocking this bin unnecessarily.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    score
}

