    let dev = (mean_residual - pr) / cap;
    score += 0.3 * dev * dev;

    // New-bin candidate: penalize opening a new bin mildly, more so early in stream
    // (so we reuse open bins unless the fit is clearly bad)
    if bin_residual == bin_capacity {
        score += 0.9 - 0.4 * progress;
        // but if the item would leave terrible residue in any existing bin, new bin is fine:
        score -= 0.5 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual % 10) as f64;
    let decade = (post_residual / 10) as f64;

    // Reward post-residuals that are "usable" harmonic classes (multiples of 5/10)
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += class * 0.4; // penalize odd dead space
    }

    // Dead space threshold: tiny unusable leftovers are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item can fit into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_class = ((post_residual - next_item_size) % 10) as f64;
        score -= 12.0 - slack_class * 0.3;
    } else if next_item_size > post_residual {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening fresh bins unless residual is tiny
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.25;
    }

    // Fraction of capacity filled (harmonic fraction coupling)
    let fill_frac = (bin_residual as f64) / cap;
    score -= fill_frac * fill_frac * 8.0;

    // Stream progression: later in stream, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * (0.05 + 0.10 * progress);

    // Many open bins: consolidate
    score += open_bins_count as f64 * 0.15;

    score
}
